from author import *
c=C('磁盘调度与外存管理')
S(c,'磁盘访问时间与单位',[T('机械磁盘读写','寻道＋旋转等待＋数据传输等'),T('7200转/分钟','每圈约8.33ms，平均旋转等待约4.17ms'),T('比较对象','机械寻道模型不能直接套给SSD')],[P('机械磁盘读取一个位置，通常先移动磁头到目标磁道，再等扇区转到磁头下方，最后传输数据。寻道、旋转等待和传输是不同部分。每分钟七千二百转，一圈是六十除以七千二百秒，约八点三三毫秒；随机位置的平均旋转等待约半圈，即四点一七毫秒。',[1,2],['每分钟转速先换成每秒周期','平均旋转等待通常按半圈估计'],phase='rotate',anchor='再等扇区转到磁头下方'),P('题目若给寻道五毫秒、传输约零点零四毫秒，简化平均访问约九点二一毫秒。控制器等其他开销是否计入，看题设。固态硬盘没有机械磁头的同类寻道过程，因此不能把磁头移动距离公式直接当成所有存储设备的统一性能公式。先确认讨论的是哪一种介质。',[3],['先确认介质与开销范围','不能把机械寻道模型泛化给SSD'],phase='seek',anchor='寻道五毫秒')],['磁盘访问时间'],visual=G('disk_mechanics'))
S(c,'FCFS与最短寻道优先',[T('请求队列','82、170、43、140、24、16、190；磁头50'),T('FCFS','按原顺序服务，移动总距离642'),T('SSTF','43→24→16→82→140→170→190，总距离208')],[P('本页磁道编号从零到一百九十九，磁头初始在五十，所有请求都已到达。先来先服务按原队列走，每段距离取相邻位置之差的绝对值，再累加。图中轨迹来回跨度大，总移动六百四十二。不要把磁道编号本身相加，也不要只算起点到最后终点的净位移。',[1,2],['每段取绝对距离后求和','总路程不等于净位移'],phase='fcfs',anchor='按原队列走'),P('最短寻道优先每次选离当前位置最近的请求。五十先到四十三，再到二十四、十六，然后转向八十二、一百四十、一百七十、一百九十，总距离二百零八。每服务一个请求后都要用新位置重新比较。持续有附近请求到来时，远处请求可能饥饿，不能只看本例路程短就说它总是公平。',[3],['SSTF每一步重新比较距离','动态到达时可能使远处请求饥饿'],phase='sstf',anchor='五十先到四十三')],['磁盘FCFS','SSTF'],visual=G('disk_schedule'))
S(c,'SCAN与LOOK的边界差别',[T('同一题设','磁道0—199，磁头50，先向编号增大方向'),T('SCAN','先到199再折返，总距离332'),T('LOOK','到本方向最远请求190折返，总距离314')],[P('扫描算法像电梯，先沿给定方向服务，再回头。本题先向编号增大方向，SCAN即使最后一个请求在一百九十，也继续到边界一百九十九，再折返服务另一侧。计入这段边界移动，总距离是三百三十二。题目必须明确初始方向，方向不同，结果会改变。',[1,2],['SCAN通常走到物理边界','初始方向是必要题设'],phase='scan',anchor='继续到边界一百九十九'),P('LOOK不必走到没有请求的最外边界，到当前方向最远请求一百九十即可回头，因此同一题设路程为三百一十四。考试如果只说扫描，要看题目是否采用SCAN、LOOK或另行给定服务规则，不要把两种折返点混用。总距离仍逐段相加，停止计算的时刻也要与题目一致。',[3],['LOOK看最远待服务请求','到边界还是到请求，不能混同'],phase='look',anchor='到当前方向最远请求一百九十')],['SCAN','LOOK'],visual=G('disk_scan'))
S(c,'循环扫描与公平性',[T('C-SCAN','只沿一个方向服务，回程通常不服务'),T('计数约定','本例回到另一端的移动也计入距离'),T('C-LOOK','只在两端最远请求之间循环，边界不同')],[P('循环扫描沿一个方向服务，走完后回到另一端，再继续同方向。回程通常不处理请求，但磁头仍然移动；题目问总路程时，若约定回程计入，就不能漏掉。本例向上，先走到一百九十九，回零，再服务低编号请求，按此约定总距离三百九十一。',[1,2],['不服务，不代表不移动','回程是否计入要读题'],phase='cscan',anchor='回零'),P('C-LOOK则在两端最远请求之间循环，不必每次走到物理边界。本例从一百九十回到十六，再向上服务二十四和四十三，计入回跳，总距离三百四十一。比较算法时要保持请求、起点、方向和回跳计数规则一致。别用一个算法算服务路程，另一个算总移动，再直接比较。',[3],['循环边界与回跳计数都要一致','同一组题设才能比较结果'],phase='clook',anchor='从一百九十回到十六')],['C-SCAN','C-LOOK'],visual=G('disk_cycle'))
S(c,'空闲空间管理与位示图',[T('位示图约定','本页1表示已占，0表示空闲'),T('空间计算','1000个盘块需1000位，即125字节'),T('实际存放','若按4KiB块存位图，至少占1块')],[P('位示图用位记录盘块是否空闲，但零和一各代表什么，要先看题目约定。本页一表示已占，零表示空闲。一千个盘块至少需要一千位，除以八得到一百二十五字节。如果题目要求它实际占几个四KiB盘块，还要向上取整，答案是一块，不是一百二十五块。',[1,2],['先看0和1的约定','位、字节、盘块分三层计算'],phase='bitmap',anchor='一千个盘块至少需要一千位'),P('空闲链表、成组链接等方法则以不同结构维护可分配块。分配时选取空闲块并更新管理信息，回收时再把块交还；不能只改目录名字而忘记回收策略。若题目给出空闲块总数，还要检查是否已经扣除了位图、目录等元数据保留块，别在同一项上重复扣减。',[3],['分配与回收都要维护空闲结构','保留块是否已扣除由题设决定'],phase='allocate',anchor='分配时选取空闲块')],['空闲空间管理','位示图'],visual=G('bitmap'))
S(c,'RAID的容量与容错',[T('RAID 0','条带化，无冗余，不提供同类容错保证'),T('RAID 1','镜像；两两配对时可用容量约为总容量一半'),T('RAID 5','N块等容量盘：约（N－1）块容量，可承受一盘故障')],[P('RAID题先问容量，再问故障条件。RAID零把数据条带分布到多盘，没有冗余，不能因为盘多就说更安全。RAID一用镜像保存副本；若按两两镜像配对，用户可用容量约为总容量一半。RAID五用分布式校验，N块等容量盘的可用容量近似为N减一块盘，并可承受单盘故障。',[1,2,3],['容量按题设的组织方式计算','RAID 0没有冗余容错']),P('这些是简化容量和容错结论，不表示所有访问都固定提升N倍。小写入可能涉及校验更新，重建时也有代价。冗余还不能代替备份：误删、软件错误或其他故障可能同时影响多份在线数据。考试计算时按给定条带、校验和故障模型推导，不把容量、性能、可靠性混成同一个指标。',[1,2,3],['性能不能只按磁盘数量直接相乘','冗余、容错、备份含义不同'])],['RAID容量与容错'])
S(c,'磁盘调度练习',[T('题设','磁道0—199，初始50；请求20、80'),T('方向与规则','向编号增大方向；最后一个请求完成后停止'),T('问题','SCAN与LOOK的总移动距离各是多少？')],[P('暂停计算。磁头从五十开始，先向编号增大方向，只有二十和八十两个请求。SCAN按本课规则走到一百九十九再折返，LOOK到最远请求就折返；最后一个请求完成后停止。请分别算两者的总移动距离，不要只写出服务请求的顺序，因为两者的服务顺序在这里可以相同。',[1,2,3],['同样服务顺序，也可能路程不同','先确定折返点'])],['磁盘管理练习'],kind='question')
S(c,'磁盘调度练习答案',[T('SCAN','50→80→199→20：149＋179＝328'),T('LOOK','50→80→20：30＋60＝90'),T('关键差别','SCAN的边界移动不能凭空省略')],[P('SCAN先走到一百九十九，五十到边界是一百四十九，再从边界回二十是一百七十九，总共三百二十八。LOOK在八十就折返，先走三十，再走六十，总共九十。若你的两个结果相同，检查是否把SCAN到物理边界的那一段漏掉了；这正是这类题常设的辨析点。',[1,2,3],['SCAN为328，LOOK为90','总路程按实际移动路径累加'])],['磁盘管理练习'],kind='answer')
c=C('I/O管理与综合回顾')
S(c,'I/O软件层次与驱动',[T('请求向下','应用与库 → 设备独立层 → 驱动 → 控制器'),T('完成向上','中断处理、状态更新与唤醒等'),T('职责区分','统一接口与具体硬件操作分层处理')],[P('应用提出读写请求以后，不是直接把所有硬件细节都写在应用里。设备独立软件提供统一管理与接口，驱动把请求转换成适合具体设备的操作，控制器再与设备交互。驱动和控制器也不同，一个主要是软件，一个是硬件管理部件。',[1,2],['驱动软件不等于硬件控制器','请求和完成通知方向不同'],phase='request',anchor='驱动把请求转换成'),P('设备完成时，可以通过中断等方式把结果通知系统。分层的作用是减少应用对具体设备的依赖，但不表示每一层都完全不关心性能和错误。请求排队、缓冲、命名、保护以及完成通知分别由相应机制处理。概念题问某操作属于哪层，先看它是在提供统一抽象，还是在操作某种设备的专有寄存器。不要见到输入输出四个字，就全部归给中断处理程序。',[3],['统一抽象和具体设备操作分开','中断处理不是全部I/O软件'],phase='complete',anchor='设备完成时')],['I/O软件层次'],visual=G('io_layers'))
S(c,'轮询、中断与DMA',[T('程序查询','处理器反复检查设备状态'),T('中断驱动','设备完成后通知处理器处理'),T('DMA','控制器按设置在设备与内存之间传送数据')],[P('查询方式让处理器反复检查设备是否准备好，等待期间也可能持续占用处理器。中断方式让设备在需要处理时发出通知，减少反复查询，但处理器仍要执行中断服务。两者的区别不是有没有操作系统，而是等待与通知的组织方式。短小、特定场景下查询也可能有用途，不能把它说成永远不可使用。',[1,2],['查询会反复检查状态','中断处理也有进入和退出成本'],phase='poll',anchor='反复检查设备是否准备好'),P('DMA把一批数据传输交给相应控制器，按设置在设备和内存之间移动，处理器不必逐字节亲自搬运。但处理器通常仍参与设置地址、长度、方向和启动操作，结束或异常时也可能需要处理。考试出现DMA完全不需要处理器参与，要判错；减少逐次搬运，不等于从开始到结束都与处理器无关。',[3],['DMA减少逐字节搬运参与','初始化和完成处理仍可能需要CPU'],phase='dma',anchor='在设备和内存之间移动')],['程序查询','中断I/O','DMA'],visual=G('dma'))
S(c,'缓冲为什么能提高效率',[T('三个时间','T：设备读入；M：复制到用户区；C：处理'),T('稳定周期简化模型','单缓冲max(T,C)＋M；双缓冲max(T,C＋M)'),T('例题','T＝10，M＝2，C＝6：稳定周期12与10')],[P('缓冲区先暂存数据，协调设备与处理器速度。用常见简化模型，T是设备读入，M是复制到用户区，C是处理。单缓冲的设备读入与复制不能同时占用同一块，但处理可与下一次读入重叠，稳定周期是T与C的较大者，再加M。这里计算的是稳定处理间隔，不是随意相加的整段总用时。',[1,2],['先明确T、M、C各表示什么','稳定周期与有限批次总时长不同'],phase='single',anchor='单缓冲的设备读入与复制'),P('双缓冲可以交替使用两个块，在模型条件下，稳定周期是T与C加M的较大者。T十、M二、C六时，单缓冲十二，双缓冲十。若题目问有限几个数据块从开始到最后完成的总时间，还要画启动、稳定和收尾阶段；若另有总线冲突或复制条件，按新约束重新排。双缓冲也不保证任何场景都把速度翻倍。',[3],['双缓冲靠重叠，不是凭空加速设备','有限批次应另画完整时间线'],phase='double',anchor='双缓冲可以交替使用两个块')],['缓冲管理'],visual=G('buffer_pipeline'))
S(c,'SPOOLing与设备独立性',[T('SPOOLing','先把输出保存到外存队列，再由服务统一发送'),T('打印场景','多个任务提交作业，物理打印机依次处理'),T('设备独立性','应用使用统一名字和接口，由系统完成映射')],[P('多个用户都想打印，可以先把打印内容保存到磁盘上的排队区。这是假脱机，也就是SPOOLing的典型场景。用户感觉可以提交自己的打印任务，但并不表示一台打印机同一时刻能物理打印几张不同作业。虚拟化的是使用方式，设备能力仍有约束。',[1,2],['排队区常在外存','提交多个任务不等于设备同时执行多个任务'],phase='spool',anchor='先把打印内容保存到磁盘'),P('随后打印服务把作业送给物理打印机，由真实设备依次完成。设备独立性让应用不必绑定某台设备的具体硬件编号，系统负责把逻辑名字映射到相应设备并完成保护。它与驱动分工、缓冲和排队共同支持方便的接口。假脱机、DMA和中断不是同一层次的三个互斥选项，系统可以把这些机制组合使用；做选择题要先看每个概念解决哪类问题。',[3],['逻辑设备名与具体硬件分开','不同层次机制可以组合使用'],phase='print',anchor='打印服务把作业送给物理打印机')],['SPOOLing','设备独立性'],visual=G('spooling'))
S(c,'一次读取怎样串起各章',[T('发起读取','描述符 → 打开状态 → 文件系统与缓存检查'),T('需要外存','请求设备，当前执行流可阻塞；调度其他任务'),T('完成返回','数据到位 → 更新状态 → 就绪 → 调度后继续')],[P('现在用一次文件读取把全课串起来。进程通过描述符发出读取请求，进入内核，系统定位打开状态和文件数据。如果缓存已经有需要的内容，不一定访问磁盘；若需要外存数据，则向设备层提交请求，当前执行流可能进入阻塞，调度器去运行其他任务。文件、内存、I/O与调度开始协同工作。',[1,2],['一次read不一定对应一次磁盘访问','缓存命中和设备读取是不同路径'],phase='read',anchor='若需要外存数据'),P('设备完成后，内核更新相关状态，原先等待的进程获得继续执行的条件，进入就绪；等调度到它，再继续处理结果并返回用户态。缺页、资源竞争和错误处理可能增加其他分支，本页只画一条常见简化路径。综合题先还原这条因果链，再判断每一步的状态、管理结构和数据位置。',[3],['完成通知不等于立刻抢到处理器','先画因果顺序，再识别各章概念'],phase='return',anchor='设备完成后')],['综合运行链'],visual=G('read_path'))
S(c,'综合判断练习',[T('判断一','使用DMA后，CPU从初始化到结束完全不参与'),T('判断二','I/O完成会让等待进程通常先回到就绪'),T('判断三','TLB未命中就一定要从磁盘调页')],[P('最后暂停判断三句话。使用DMA后，处理器从初始化到结束完全不用参与。输入输出完成后，等待它的进程通常先回到就绪。快表未命中，就一定要从磁盘调入页面。每一句都指出你采用的依据，并把它对应到设备管理、进程状态或地址变换，避免只背正确或错误的字样。',[1,2,3],['DMA参与范围','就绪与运行','快表未命中与缺页'])],['综合练习'],kind='question')
S(c,'综合判断练习答案',[T('第一句错误','DMA仍常需CPU初始化、启动和完成处理'),T('第二句正确','事件满足后可就绪，运行仍需调度'),T('第三句错误','TLB未命中还可查页表，页面可能已驻留')],[P('第一句错，DMA减少逐次数据搬运，并没有消除初始化与完成处理。第二句对，事件完成通常使等待者转为就绪，后续运行由调度决定。第三句错，快表没有这条映射，可以继续查页表；只有合法访问的页面确实未驻留时，才走缺页调入路径。三种机制分开，综合题才不会串错因果。',[1,2,3],['区分机制解决的问题','不要把任何未命中都叫缺页'])],['综合练习'],kind='answer')
S(c,'十章回顾与考前做题顺序',[T('先找对象和状态','进程、线程、页、页框、文件、设备分别定位'),T('再定算法与题设','到达、初值、页框数、方向、缓存和开销'),T('最后计算与检查','画表逐步更新，核对单位、边界与总量')],[P('回顾这十章，先分清对象：进程线程管执行，页与页框管映射，目录和索引管文件，控制器和驱动管设备。计算前把题设写在纸上：任务何时到达、信号量初值多少、页框是否为空、磁头先往哪走、哪些信息已经缓存。不同题设下，同一个算法名也可能得到不同数字。',[1,2],['对象先分清，题设先列全','状态与数据位置要对应']),P('做题按三步推进：先画时间线或结构图，再逐项更新状态，最后检查总量和单位。调度检查服务时间是否用完，银行家检查资源是否守恒，分页检查偏移是否越界，磁盘检查每段路程是否计入。看完课程以后，先独立重做十道练习，再用往年基础题补齐速度和书写。框架建立起来，才有条件继续训练综合题。',[3],['先独立重做，再核对答案','基础框架不能代替后续真题训练'])],['综合回顾'])

